# -*- coding: utf-8 -*-
"""Descriptions shared by the constructed variables of several SCP deposits (CONSTRUCTED in the survey modules)."""
GEN = "generation from the respondent's and parents' countries of birth (first generation = born abroad; second = born in the Netherlands with at least one parent born abroad)"
GENP = "partner's generation from the partner's country of birth: 1 = born abroad, 2 = born in the Netherlands, native Dutch partners included; partners of native Dutch respondents are not classed (the parents' clause of the generation definition is not applied - SIM 2006 deposit, restricted component, 5 Nov 2026)"
ETN = "origin group from the respondent's and parents' countries of birth (CBS definition: a person belongs to a group when he/she or at least one parent was born in that country)"
BB = "labour-force position (employed >= 12 hours a week / unemployed and seeking work / not in the labour force) from the questions on paid work, hours and job search"
OND = "full-time education participation from the questions on current education and main activity"
